<template>
  <AppShell eyebrow="Admin-Zentrale" title="Alle Kalender" description="Gesamtübersicht aller geplanten Dienste – nach Ort oder Mitarbeiter filterbar.">
    <section class="toolbar panel">
      <label><span>Monat</span><input v-model="monthValue" type="month"></label>
      <label><span>Ort</span><select v-model="locationFilter"><option value="all">Alle Orte</option><option v-for="location in locations" :key="location.id" :value="location.name">{{ location.name }}</option></select></label>
      <label><span>Mitarbeiter</span><select v-model="employeeFilter"><option value="all">Alle Mitarbeiter</option><option v-for="employee in employees" :key="employee.id" :value="employee.id">{{ employee.name }}</option></select></label>
      <button type="button" :disabled="isLoading" @click="loadCalendar"><i class="fa-solid fa-rotate-right"></i> Aktualisieren</button>
    </section>

    <section class="summary-grid"><article><i class="fa-solid fa-calendar-check"></i><span>Geplante Dienste</span><strong>{{ visibleSchedules.length }}</strong></article><article><i class="fa-solid fa-sun"></i><span>Tagdienste</span><strong>{{ dayShifts }}</strong></article><article><i class="fa-solid fa-moon"></i><span>Nachtdienste</span><strong>{{ nightShifts }}</strong></article></section>

    <section class="calendar-panel panel"><header><div><p>GESAMTÜBERSICHT</p><h2>{{ monthLabel }}</h2><span>Name zuerst, danach die Dienste des Monats. Heute ist eingerahmt.</span></div><div class="legend"><span><i class="dot day"></i> Tagdienst</span><span><i class="dot night"></i> Nachtdienst</span><span><i class="dot vacation"></i> Urlaub / Krank</span></div></header><div v-if="isLoading" class="state"><i class="fa-solid fa-spinner fa-spin"></i> Kalender wird geladen …</div><div v-else class="roster-wrap"><table class="roster-table"><thead><tr><th class="person-head">Mitarbeiter:in</th><th v-for="day in calendarDays" :key="day.date" :class="{ today: day.today }"><strong>{{ day.number }}</strong><small>{{ weekdayFor(day.date) }}</small></th></tr></thead><tbody><tr v-for="employee in visibleEmployees" :key="employee.id"><th scope="row" class="person-cell"><strong>{{ employee.name }}</strong><small>{{ employeeShiftCount(employee.id) }} Dienst{{ employeeShiftCount(employee.id) === 1 ? '' : 'e' }}</small></th><td v-for="day in calendarDays" :key="`${employee.id}-${day.date}`" :class="{ today: day.today }"><div v-for="shift in shiftsFor(employee.id, day.date)" :key="shift.id" class="roster-shift" :class="shift.vacation ? 'vacation' : (shift.is_night ? 'night' : 'day')"><b>{{ shift.vacation ? 'FREI' : (shift.is_night ? 'ND' : 'TD') }}</b><span>{{ shift.ort }}</span></div><em v-if="!shiftsFor(employee.id, day.date).length">–</em></td></tr><tr v-if="!visibleEmployees.length"><td class="empty-roster" :colspan="calendarDays.length + 1">Für diesen Filter gibt es keine Mitarbeitenden.</td></tr></tbody></table></div></section>
  </AppShell>
</template>

<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import AppShell from '../components/AppShell.vue'
import { supabase } from '../config/supabase.js'

const now = new Date()
const monthValue = ref(`${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`)
const locations = ref([])
const employees = ref([])
const schedules = ref([])
const isLoading = ref(true)
const locationFilter = ref('all')
const employeeFilter = ref('all')
const selectedYear = computed(() => Number(monthValue.value.slice(0, 4)))
const selectedMonth = computed(() => Number(monthValue.value.slice(5, 7)))
const monthStart = computed(() => `${monthValue.value}-01`)
const monthEnd = computed(() => `${monthValue.value}-${String(new Date(selectedYear.value, selectedMonth.value, 0).getDate()).padStart(2, '0')}`)
const monthLabel = computed(() => new Intl.DateTimeFormat('de-AT', { month: 'long', year: 'numeric' }).format(new Date(selectedYear.value, selectedMonth.value - 1, 1)))
const visibleSchedules = computed(() => schedules.value.filter((shift) => (locationFilter.value === 'all' || shift.ort === locationFilter.value) && (employeeFilter.value === 'all' || shift.user_id === employeeFilter.value)))
const dayShifts = computed(() => visibleSchedules.value.filter((shift) => !shift.is_night).length)
const nightShifts = computed(() => visibleSchedules.value.filter((shift) => shift.is_night).length)
const visibleEmployees = computed(() => employees.value.filter((employee) => employeeFilter.value === 'all' || employee.id === employeeFilter.value))
const calendarDays = computed(() => {
  const today = new Date().toISOString().slice(0, 10); const count = new Date(selectedYear.value, selectedMonth.value, 0).getDate()
  return Array.from({ length: count }, (_, index) => { const number = index + 1; const date = `${monthValue.value}-${String(number).padStart(2, '0')}`; return { number, date, today: date === today } })
})
const shiftsFor = (employeeId, date) => visibleSchedules.value.filter((shift) => shift.user_id === employeeId && shift.date === date)
const employeeShiftCount = (employeeId) => visibleSchedules.value.filter((shift) => shift.user_id === employeeId).length
const weekdayFor = (date) => new Intl.DateTimeFormat('de-AT', { weekday: 'short' }).format(new Date(`${date}T12:00:00`)).replace('.', '')

const loadCalendar = async () => {
  isLoading.value = true
  try {
    const [{ data: locationRows, error: locationError }, { data: employeeRows, error: employeeError }, { data: scheduleRows, error: scheduleError }] = await Promise.all([
      supabase.from('work_locations').select('id, name').order('name'),
      supabase.from('app_users').select('id, name').eq('role', 'employee').order('name'),
      supabase.from('schedules').select('id, user_id, date, ort, shift_time, is_night, vacation').gte('date', monthStart.value).lte('date', monthEnd.value).order('date')
    ])
    if (locationError || employeeError || scheduleError) throw locationError || employeeError || scheduleError
    locations.value = locationRows || []; employees.value = employeeRows || []; schedules.value = scheduleRows || []
  } finally { isLoading.value = false }
}
watch(monthValue, loadCalendar)
onMounted(loadCalendar)
</script>

<style scoped>
