header span { display: block; margin-top: 5px; color: var(--text-secondary); font-size: .69rem; }.legend { display: flex; gap: 12px; color: var(--text-secondary); font-size: .66rem; font-weight: 700; }.legend span { display: inline-flex; align-items: center; gap: 5px; }.dot { width: 7px; height: 7px; border-radius: 99px; }.dot.day { background: #60a5fa; }.dot.night { background: #a78bfa; }.state { min-height: 320px; display: grid; place-content: center; justify-items: center; gap: 10px; color: var(--text-muted); font-size: .8rem; }.calendar-wrap { overflow-x: auto; padding: 13px; }.weekday-row, .grid { min-width: 730px; display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 6px; }.weekday-row { margin-bottom: 6px; }.weekday-row span { padding: 3px; color: var(--text-muted); font-size: .61rem; font-weight: 800; text-align: center; text-transform: uppercase; }.day-card { min-height: 130px; padding: 8px; border: 1px solid var(--line); border-radius: 10px; background: var(--surface-soft); }.day-card.today { border-color: #60a5fa; box-shadow: inset 0 0 0 1px rgba(96,165,250,.45); }.day-card > header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px; }.day-card header strong { color: var(--text-heading); font-size: .74rem; }.day-card header small { color: var(--text-muted); font-size: .5rem; }.shifts { display: grid; gap: 4px; }.chip { display: grid; grid-template-columns: 20px minmax(0,1fr); gap: 2px 4px; padding: 4px; border-radius: 6px; color: #dbeafe; font-size: .54rem; }.chip b { grid-row: span 2; padding: 3px 0; border-radius: 4px; color: #fff; background: rgba(255,255,255,.18); font-size: .47rem; text-align: center; }.chip span, .chip small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.chip small { opacity: .8; font-size: .46rem; }.chip.day { background: rgba(37,99,235,.23); }.chip.night { background: rgba(124,58,237,.23); }.shifts em { color: var(--text-muted); font-size: .68rem; font-style: normal; }
@media (max-width: 650px) { .toolbar { grid-template-columns: 1fr 1fr; }.toolbar button { grid-column: span 2; }.summary-grid { gap: 7px; }.summary-grid article { grid-template-columns: 1fr; min-height: 78px; gap: 3px; padding: 10px; }.summary-grid i { width: 26px; height: 26px; grid-row: auto; border-radius: 8px; font-size: .65rem; }.summary-grid span { overflow: hidden; font-size: .56rem; text-overflow: ellipsis; white-space: nowrap; }.calendar-panel > header { align-items: flex-start; flex-direction: column; padding: 18px; }.legend { width: 100%; justify-content: space-between; }.calendar-wrap { padding: 9px; } }
.dot.vacation { background: #34d399; }.chip.vacation { color: #bbf7d0; background: rgba(16,185,129,.19); }
.roster-wrap { overflow: auto; max-height: min(67vh, 710px); }.roster-table { width: 100%; min-width: 1120px; border-collapse: separate; border-spacing: 0; }.roster-table th, .roster-table td { min-width: 54px; padding: 8px 5px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); vertical-align: top; text-align: center; }.roster-table thead th { position: sticky; top: 0; z-index: 3; color: var(--text-secondary); background: var(--surface-raised); font-size: .61rem; font-weight: 800; }.roster-table thead strong { display: block; color: var(--text-heading); font-size: .75rem; }.roster-table thead small { display: block; margin-top: 2px; font-size: .51rem; text-transform: uppercase; }.roster-table .person-head, .roster-table .person-cell { position: sticky; left: 0; z-index: 4; min-width: 155px; max-width: 155px; border-right: 1px solid var(--line-strong); text-align: left; background: var(--surface-card); }.roster-table .person-head { z-index: 5; padding-left: 14px; }.roster-table .person-cell { padding: 11px 13px; }.person-cell strong { display: block; overflow: hidden; color: var(--text-heading); font-size: .72rem; text-overflow: ellipsis; white-space: nowrap; }.person-cell small { display: block; margin-top: 4px; color: var(--text-muted); font-size: .57rem; font-weight: 600; }.roster-table tbody tr:hover td, .roster-table tbody tr:hover .person-cell { background: var(--surface-soft); }.roster-table th.today, .roster-table td.today { background-color: rgba(37,99,235,.055); box-shadow: inset 1px 0 0 rgba(96,165,250,.6), inset -1px 0 0 rgba(96,165,250,.6); }.roster-table thead th.today { box-shadow: inset 1px 0 0 #60a5fa, inset -1px 0 0 #60a5fa, inset 0 2px 0 #60a5fa; }.roster-table td em { display: block; padding-top: 3px; color: var(--text-muted); font-size: .65rem; font-style: normal; }.roster-shift { display: grid; gap: 2px; margin-bottom: 4px; padding: 4px 2px; border-radius: 6px; color: #dbeafe; font-size: .49rem; line-height: 1.15; }.roster-shift:last-child { margin-bottom: 0; }.roster-shift b { padding: 2px; border-radius: 4px; color: #fff; background: rgba(255,255,255,.18); font-size: .46rem; }.roster-shift span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.roster-shift.day { background: rgba(37,99,235,.24); }.roster-shift.night { background: rgba(124,58,237,.24); }.roster-shift.vacation { color: #bbf7d0; background: rgba(16,185,129,.2); }.empty-roster { padding: 36px !important; color: var(--text-muted); text-align: center !important; }
